//! kvhttp: an in-memory HTTP/1.1 key-value server.

mod server;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use hyper::server::conn::http1;
use hyper::service::service_fn;
use hyper_util::rt::TokioIo;
use tokio::net::TcpListener;

use crate::store::KvStore;

fn parse_port(arg: Option<String>) -> Option<u16> {
    arg?.parse::<u16>().ok().filter(|&p| p != 0)
}

#[tokio::main]
async fn main() -> ExitCode {
    let Some(port) = parse_port(std::env::args().nth(1)) else {
        eprintln!("usage: app <port>");
        return ExitCode::from(2);
    };

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = match TcpListener::bind(addr).await {
        Ok(listener) => listener,
        Err(err) => {
            eprintln!("server error: {err}");
            return ExitCode::FAILURE;
        }
    };
    println!("kvhttp listening on http://{addr}");

    tokio::select! {
        () = serve(listener, Arc::new(KvStore::new())) => ExitCode::FAILURE,
        _ = shutdown_signal() => ExitCode::SUCCESS,
    }
}

async fn serve(listener: TcpListener, store: Arc<KvStore>) {
    loop {
        let (stream, _) = match listener.accept().await {
            Ok(conn) => conn,
            Err(err) => {
                // Transient failures (e.g. EMFILE) must not bring the server down.
                eprintln!("accept error: {err}");
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
                continue;
            }
        };
        let _ = stream.set_nodelay(true);
        let store = Arc::clone(&store);
        tokio::spawn(async move {
            let service = service_fn(move |req| server::handle(Arc::clone(&store), req));
            if let Err(err) = http1::Builder::new()
                .serve_connection(TokioIo::new(stream), service)
                .await
                && !err.is_incomplete_message()
            {
                eprintln!("connection error: {err}");
            }
        });
    }
}

async fn shutdown_signal() {
    use tokio::signal::unix::{SignalKind, signal};
    let (Ok(mut term), Ok(mut int)) = (
        signal(SignalKind::terminate()),
        signal(SignalKind::interrupt()),
    ) else {
        std::future::pending::<()>().await;
        return;
    };
    tokio::select! {
        _ = term.recv() => {}
        _ = int.recv() => {}
    }
}

//! HTTP routing and request handling.

use std::sync::Arc;

use bytes::Bytes;
use http_body_util::{BodyExt, Full, LengthLimitError, Limited};
use hyper::body::Incoming;
use hyper::header::{ALLOW, CONTENT_LENGTH, CONTENT_TYPE, HeaderValue};
use hyper::{Method, Request, Response, StatusCode};

use crate::store::KvStore;

pub const MAX_VALUE_BYTES: usize = 1024 * 1024;
const KV_PREFIX: &str = "/kv/";
const MAX_KEY_LEN: usize = 64;

const TEXT_PLAIN: &str = "text/plain; charset=utf-8";
const OCTET_STREAM: &str = "application/octet-stream";
const JSON: &str = "application/json";

/// A request failure that maps directly onto an HTTP error response.
#[derive(Debug)]
enum HttpError {
    BadRequest(&'static str),
    NotFound,
    MethodNotAllowed(&'static str),
    PayloadTooLarge,
    Internal,
}

impl HttpError {
    fn into_response(self) -> Response<Full<Bytes>> {
        let (status, message) = match self {
            Self::BadRequest(msg) => (StatusCode::BAD_REQUEST, msg),
            Self::NotFound => (StatusCode::NOT_FOUND, "Not Found"),
            Self::MethodNotAllowed(_) => (StatusCode::METHOD_NOT_ALLOWED, "Method Not Allowed"),
            Self::PayloadTooLarge => (StatusCode::PAYLOAD_TOO_LARGE, "Payload Too Large"),
            Self::Internal => (StatusCode::INTERNAL_SERVER_ERROR, "internal error"),
        };
        let mut res = respond(status, Bytes::from_static(message.as_bytes()), TEXT_PLAIN);
        if let Self::MethodNotAllowed(allowed) = self {
            res.headers_mut()
                .insert(ALLOW, HeaderValue::from_static(allowed));
        }
        res
    }
}

/// Builds a response with an explicit `Content-Length`, and a `Content-Type` when non-empty.
fn respond(status: StatusCode, body: Bytes, content_type: &'static str) -> Response<Full<Bytes>> {
    let len = body.len();
    let mut res = Response::new(Full::new(body));
    *res.status_mut() = status;
    let headers = res.headers_mut();
    headers.insert(CONTENT_LENGTH, HeaderValue::from(len));
    if len > 0 {
        headers.insert(CONTENT_TYPE, HeaderValue::from_static(content_type));
    }
    res
}

fn empty(status: StatusCode) -> Response<Full<Bytes>> {
    respond(status, Bytes::new(), TEXT_PLAIN)
}

fn is_valid_key(key: &str) -> bool {
    (1..=MAX_KEY_LEN).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

async fn read_body(body: Incoming, declared: Option<&HeaderValue>) -> Result<Bytes, HttpError> {
    let declared = declared
        .and_then(|v| v.to_str().ok())
        .and_then(|v| v.trim().parse::<u64>().ok());
    if declared.is_some_and(|len| len > MAX_VALUE_BYTES as u64) {
        return Err(HttpError::PayloadTooLarge);
    }
    match Limited::new(body, MAX_VALUE_BYTES).collect().await {
        Ok(collected) => Ok(collected.to_bytes()),
        Err(err) if err.is::<LengthLimitError>() => Err(HttpError::PayloadTooLarge),
        Err(_) => Err(HttpError::BadRequest("invalid body")),
    }
}

async fn route(
    store: &KvStore,
    req: Request<Incoming>,
) -> Result<Response<Full<Bytes>>, HttpError> {
    let path = req.uri().path();

    match path {
        "/health" => {
            if req.method() != Method::GET {
                return Err(HttpError::MethodNotAllowed("GET"));
            }
            Ok(respond(
                StatusCode::OK,
                Bytes::from_static(b"ok"),
                TEXT_PLAIN,
            ))
        }
        "/kv" => {
            if req.method() != Method::GET {
                return Err(HttpError::MethodNotAllowed("GET"));
            }
            let json = serde_json::to_vec(&store.keys()).map_err(|_| HttpError::Internal)?;
            Ok(respond(StatusCode::OK, json.into(), JSON))
        }
        _ => {
            let Some(key) = path.strip_prefix(KV_PREFIX) else {
                return Err(HttpError::NotFound);
            };
            if !is_valid_key(key) {
                return Err(HttpError::BadRequest("invalid key"));
            }
            let key = key.to_owned();

            match *req.method() {
                Method::GET => {
                    let value = store.get(&key).ok_or(HttpError::NotFound)?;
                    Ok(respond(StatusCode::OK, value, OCTET_STREAM))
                }
                Method::PUT => {
                    let (parts, body) = req.into_parts();
                    let value = read_body(body, parts.headers.get(CONTENT_LENGTH)).await?;
                    let status = if store.set(&key, value) {
                        StatusCode::CREATED
                    } else {
                        StatusCode::OK
                    };
                    Ok(empty(status))
                }
                Method::DELETE => {
                    if store.delete(&key) {
                        Ok(empty(StatusCode::NO_CONTENT))
                    } else {
                        Err(HttpError::NotFound)
                    }
                }
                _ => Err(HttpError::MethodNotAllowed("GET, PUT, DELETE")),
            }
        }
    }
}

/// Handles a single request, converting routing errors into HTTP responses.
pub async fn handle(
    store: Arc<KvStore>,
    req: Request<Incoming>,
) -> Result<Response<Full<Bytes>>, std::convert::Infallible> {
    Ok(route(&store, req)
        .await
        .unwrap_or_else(HttpError::into_response))
}

#[cfg(test)]
mod tests {
    use super::is_valid_key;

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("é"));
    }
}

//! In-memory key-value store holding raw byte values.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock};

use bytes::Bytes;

/// Thread-safe map from keys to byte values; keys are kept sorted.
#[derive(Debug, Default)]
pub struct KvStore {
    data: RwLock<BTreeMap<String, Bytes>>,
}

impl KvStore {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn get(&self, key: &str) -> Option<Bytes> {
        self.read().get(key).cloned()
    }

    /// Stores `value` under `key`; returns `true` if the key was newly created.
    pub fn set(&self, key: &str, value: Bytes) -> bool {
        self.write().insert(key.to_owned(), value).is_none()
    }

    /// Removes `key`; returns `true` if it was present.
    pub fn delete(&self, key: &str) -> bool {
        self.write().remove(key).is_some()
    }

    /// All keys, sorted ascending by byte order.
    pub fn keys(&self) -> Vec<String> {
        self.read().keys().cloned().collect()
    }

    // The map holds no invariants a panicking writer could break, so poisoning is ignored.
    fn read(&self) -> std::sync::RwLockReadGuard<'_, BTreeMap<String, Bytes>> {
        self.data.read().unwrap_or_else(PoisonError::into_inner)
    }

    fn write(&self) -> std::sync::RwLockWriteGuard<'_, BTreeMap<String, Bytes>> {
        self.data.write().unwrap_or_else(PoisonError::into_inner)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn crud_and_sorted_keys() {
        let store = KvStore::new();
        assert!(store.set("b", Bytes::from_static(b"2")));
        assert!(store.set("a", Bytes::from_static(b"1")));
        assert!(!store.set("a", Bytes::from_static(b"x")));
        assert_eq!(store.get("a").as_deref(), Some(&b"x"[..]));
        assert_eq!(store.keys(), ["a", "b"]);
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }
}
